CREATE TABLE DEPARTMENT ( deptno INT PRIMARY KEY, dname VARCHAR(20), location VARCHAR(20) );
CREATE TABLE FACULTY ( facultyid VARCHAR(5) PRIMARY KEY, fname VARCHAR(15) NOT NULL, classroom_no INT, designation VARCHAR(20), deptno INT, sal INT(10), FOREIGN KEY (deptno) REFERENCES DEPARTMENT(deptno) );
CREATE TABLE STUDENT ( studentid INT PRIMARY KEY, sname VARCHAR(15) NOT NULL, birthdate DATE, facultyid VARCHAR(5), city VARCHAR(20), FOREIGN KEY (facultyid) REFERENCES FACULTY(facultyid) );
