SELECT * FROM STUDENT WHERE sname LIKE 'K%';
SELECT * FROM STUDENT WHERE sname LIKE '%R';
SELECT * FROM STUDENT WHERE sname LIKE '%E%';
SELECT * FROM FACULTY WHERE sal > 32000;
SELECT * FROM FACULTY WHERE sal < 36000 AND designation = 'Programmer';
