SELECT * FROM DEPARTMENT WHERE dname != 'OPERATIONS';
SELECT * FROM DEPARTMENT WHERE deptno BETWEEN 30 AND 50;
SELECT * FROM STUDENT ORDER BY sname ASC;
SELECT * FROM STUDENT ORDER BY sname DESC;
